window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-78f6194e34bbcbee"]={"versions": [{"id": "FIG-78f6194e34bbcbee", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<code>act EthTSyn Time Master Timesync Message Transmission</code>), ausgeführt im zyklischen Kontext der <code>EthTSyn_MainFunction()</code>.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der normativen Sende- und Zustandslogik eines <em>Time Masters</em> (bzw. Switch-Ports mit Master-Rolle) im BSW-Modul <code>EthTSyn</code> (AUTOSAR Classic Platform, Time Synchronization over Ethernet nach IEEE 802.1AS / gPTP) gemäß SWS-Anforderung <code>[SWS_EthTSyn_00265]</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Modul <code>EthTSyn</code> vermittelt zwischen dem synchronisierten Zeitbasis-Management (<code>StbM</code> – Synchronized Time-Base Manager) und der Ethernet-Treiber-/Interface-Schicht (<code>EthIf</code> / <code>Eth</code>).\n</li><li>Der Ablauf steuert die zeitliche Entprellung, zyklische/ereignisbasierte Transmission von <code>SYNC</code>- und <code>Follow_Up</code> (<code>FUP</code>)-Nachrichten sowie die asynchrone Bestätigungsverarbeitung (<code>TxConfirmation</code>) für eine gegebene Time Domain.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Zähler (pro <code>TimeDomain</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>cyclicCounter[TimeDomain]</code>:</strong> Laufzeit-Herunterzähler für die zyklische <code>SYNC</code>-Übertragung; wird mit <code>EthTSynGlobalTimeTxPeriod</code> initialisiert.\n</li><li><strong><code>debounceCounter[TimeDomain]</code>:</strong> Entprellzähler zur Einhaltung von Mindestabständen zwischen aufeinanderfolgenden Übertragungen; wird mit <code>EthTSynGlobalTimeDebounceTime</code> initialisiert.\n</li><li><strong><code>cyclicMsgResumeCounter[TimeDomain]</code>:</strong> Haltezähler nach einer unmittelbaren/ereignisgesteuerten Synchronisation (<code>Immediate Time Sync</code>); wird mit <code>EthTSynCyclicMsgResumeTime</code> initialisiert, um die zyklische Übertragung temporär zu unterdrücken.\n</li><li><strong>Protokollzustand (<code>protocol state</code>):</strong> Diskreter Zustandsmerker pro Time Domain mit den Werten <code>&quot;SYNC&quot;</code> und <code>&quot;FUP&quot;</code>.\n</li><li><strong><code>timeBaseUpdateCounter[timeBaseId]</code>:</strong> Aus dem <code>StbM</code> bezogener Update-Zähler zur Erkennung von Zeitbasisaktualisierungen.\n</li><li><strong><code>timeBaseStatus[timeBaseId]</code>:</strong> Bitmaske des Zeitstatus (Prüfung gegen Statusflag <code>GLOBAL_TIME_BASE</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurationsparameter (ECUC-Parameter)</h5>\n<ul class=\"fig-list\"><li><strong><code>EthTSynImmediateTimeSync</code> (Boolean):</strong> Aktiviert die unmittelbare Aussendung bei Aktualisierung der lokalen Zeitbasis.\n</li><li><strong><code>EthTSynGlobalTimeTxPeriod</code> (Float/Time):</strong> Zykluszeit für periodische <code>SYNC</code>-Frames.\n</li><li><strong><code>EthTSynGlobalTimeDebounceTime</code> (Float/Time):</strong> Mindestabstand zwischen Frames.\n</li><li><strong><code>EthTSynCyclicMsgResumeTime</code> (Float/Time):</strong> Verzögerungszeit bis zur Wiederaufnahme regulärer Zyklen nach einem Immediate Sync.\n</li><li><strong><code>EthTSynGlobalTimeFollowUpTimeout</code> (Float/Time):</strong> Maximales Zeitfenster für den Empfang der Tx-Bestätigung (Egress-Timestamp) des <code>SYNC</code>-Frames.\n</li></ul>\n<h5 class=\"fig-section-h5\">Interaktionsschnittstellen &amp; APIs</h5>\n<ul class=\"fig-list\"><li><strong>Unterlagerter Stack (<code>EthIf</code> / <code>Eth</code>):</strong>\n<ul class=\"fig-list\"><li>Sendeanforderung: <code>EthIf_Transmit()</code> für PTP-Frames.\n</li><li>Bestätigung &amp; Timestamping: Asynchroner Callback <code>EthIf_TxConfirmation()</code> liefert <code>E_OK</code> und den hardwarenah erfassten Egress-Sendezeitpunkt t_1.\n</li></ul>\n</li><li><strong>Oberlagerter Stack (<code>StbM</code>):</strong>\n<ul class=\"fig-list\"><li>Bereitstellung von Zeitbasis, Statusflags (<code>GLOBAL_TIME_BASE</code>) und dem <code>timeBaseUpdateCounter</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Jeder Durchlauf in der Task-Schleife der <code>EthTSyn_MainFunction()</code> folgt einer vierphasigen Kaskade:</p>\n<h5 class=\"fig-section-h5\">Phase 1: Zähler-Dekrementierung</h5>\n<p class=\"fig-p\">Parallel bzw. sequenziell werden aktive Zähler dekrementiert:</p>\n<ol class=\"fig-list\"><li>Falls <code>EthTSynImmediateTimeSync == TRUE</code> und <code>cyclicMsgResumeCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeDebounceTime &gt; 0</code> und <code>debounceCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeTxPeriod &gt; 0</code> und <code>cyclicCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Transmissions- und Quittierungsprüfung (<code>Timesync Message pending?</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Pfad <code>ongoing and not completed yet</code>:</strong> Es steht noch eine Tx-Bestätigung aus (kein Callback erfolgt). Keine Neuübertragung möglich; Verzweigung direkt zum Endknoten.\n</li><li><strong>Pfad <code>SYNC transmission completed</code>:</strong> Tx-Confirmation für <code>SYNC</code> wurde empfangen:\n<ul class=\"fig-list\"><li><em>Prüfung:</em> Erfolgreich (<code>E_OK</code>) innerhalb des Timeout-Fensters <code>EthTSynGlobalTimeFollowUpTimeout</code>?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Setze <code>protocol state = &quot;FUP&quot;</code>. Falls Nachrichtentyp <code>immediate</code>: Setze <code>cyclicMsgResumeCounter = EthTSynCyclicMsgResumeTime</code> und setze <code>cyclicCounter = 0</code>. Anschließend: Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein (Timeout/Fehler):</strong> Abbruch des Sequenzschritts, Verzweigung zum Zyklusende.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>FUP transmission completed</code>:</strong> Tx-Confirmation für <code>FUP</code> wurde empfangen:\n<ul class=\"fig-list\"><li>Setze <code>protocol state = &quot;SYNC&quot;</code>.\n</li><li><em>Prüfung:</em> War <code>FUP</code>-Übertragung erfolgreich?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein:</strong> Kein Reset des Debounce-Counters.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>no transmission ongoing</code>:</strong> Direkter Übergang zur Sendeentscheidung (Phase 3).\n</li></ul>\n<h5 class=\"fig-section-h5\">Phase 3: Sendeentscheidung &amp; Arbitrierung</h5>\n<p class=\"fig-p\">Voraussetzung für jegliche Transmission ist <code>debounceCounter[TimeDomain] == 0</code>. Ist dieser &gt; 0, terminiert der Durchlauf ohne Sendeaktion.</p>\n<ol class=\"fig-list\"><li><strong>Prüfung Protokollzustand:</strong>\n<ul class=\"fig-list\"><li>Ist <code>protocol state != &quot;SYNC&quot;</code> (d. h. <code>&quot;FUP&quot;</code>):\n<ul class=\"fig-list\"><li><strong>Aktion:</strong> <code>Transmit FUP Message</code> (Aussendung der <code>Follow_Up</code>-Nachricht mit dem im vorangegangenen Sync-Tx-Confirmation ermittelten präzisen Egress-Timestamp t_1).\n</li></ul>\n</li></ul>\n</li><li><strong>Wenn <code>protocol state == &quot;SYNC&quot;</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Pfad A – Immediate Sync:</strong> Falls <code>EthTSynImmediateTimeSync == TRUE</code>:\n<ul class=\"fig-list\"><li>Prüfung: Hat sich <code>timeBaseUpdateCounter[timeBaseId]</code> geändert <strong>UND</strong> ist Bit <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> gesetzt?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Immediate Sync Message</code> (sofortige Triggerung).\n</li><li><strong>Nein:</strong> Fallback auf Pfad B via <code>cyclicMsgResumeCounter == 0?</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad B – Cyclic Sync:</strong> Wenn <code>cyclicMsgResumeCounter == 0</code> (oder <code>ImmediateTimeSync == FALSE</code>):\n<ul class=\"fig-list\"><li>Prüfung: <code>(EthTSynGlobalTimeTxPeriod &gt; 0) &amp;&amp; (cyclicCounter == 0) &amp;&amp; (timeBaseStatus &amp; GLOBAL_TIME_BASE)</code>:\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Cyclic Sync Message</code> und Re-Initialisierung: <code>cyclicCounter = EthTSynGlobalTimeTxPeriod</code>.\n</li><li><strong>Nein:</strong> Keine Übertragung in diesem Zyklus.\n</li></ul>\n</li></ul>\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Two-Step Sync Mechanismus (IEEE 802.1AS):</strong> Das Diagramm bildet zwingend das Two-Step-Verfahren ab. Ein <code>FUP</code>-Frame kann erst übertragen werden, nachdem der Egress-Timestamp des vorhergehenden <code>SYNC</code>-Frames per <code>TxConfirmation</code> erfolgreich vom Hardware-Ethernet-Controller an das BSW gemeldet wurde.\n</li><li><strong>Hard Deadlines &amp; Timeout-Handling:</strong>\n<ul class=\"fig-list\"><li>Bleibt die Tx-Bestätigung über <code>EthTSynGlobalTimeFollowUpTimeout</code> hinaus aus, verwirft der Stack die Sequenz (kein <code>FUP</code>). Die Time Slaves erkennen den fehlenden Follow-Up und verwerfen den unvollständigen Sync-Zyklus.\n</li></ul>\n</li><li><strong>Jitter- und Periodizitäts-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die Auflösung aller Zähler hängt strikt von der Periodizität der Task ab, in der <code>EthTSyn_MainFunction()</code> aufgerufen wird (z. B. 1 ms oder 5 ms). Die konfigurierten ECUC-Parameter (<code>TxPeriod</code>, <code>DebounceTime</code>, <code>FollowUpTimeout</code>) müssen ganzzahlige Vielfache dieses Task-Intervalls sein.\n</li></ul>\n</li><li><strong>Einfluss von <code>ImmediateTimeSync</code>:</strong>\n<ul class=\"fig-list\"><li>Durch das Setzen von <code>cyclicCounter = 0</code> und Aufziehen des <code>cyclicMsgResumeCounter</code> bei einem unmittelbaren Sync wird eine Phasensynchronisation des zyklischen Senders erzwungen. Dies verhindert ein direktes Aufeinanderfolgen eines ereignisbasierten und eines regulär-zyklischen Sync-Frames („Burst Protection“).\n</li></ul>\n</li><li><strong>Voraussetzung an den StbM:</strong>\n<ul class=\"fig-list\"><li>Ohne gesetztes Status-Flag <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> unterdrückt die Logik sowohl zyklische als auch Immediate-Sync-Nachrichten, um die Verbreitung nicht synchronisierter bzw. ungültiger Master-Zeiten im Netzwerk zu unterbinden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2028f8ea3f62ff30", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<code>act EthTSyn Time Master Timesync Message Transmission</code>), ausgeführt im zyklischen Kontext der <code>EthTSyn_MainFunction()</code>.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der normativen Sende- und Zustandslogik eines <em>Time Masters</em> (bzw. Switch-Ports mit Master-Rolle) im BSW-Modul <code>EthTSyn</code> (AUTOSAR Classic Platform, Time Synchronization over Ethernet nach IEEE 802.1AS / gPTP) gemäß SWS-Anforderung <code>[SWS_EthTSyn_00265]</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Modul <code>EthTSyn</code> vermittelt zwischen dem synchronisierten Zeitbasis-Management (<code>StbM</code> – Synchronized Time-Base Manager) und der Ethernet-Treiber-/Interface-Schicht (<code>EthIf</code> / <code>Eth</code>).\n</li><li>Der Ablauf steuert die zeitliche Entprellung, zyklische/ereignisbasierte Transmission von <code>SYNC</code>- und <code>Follow_Up</code> (<code>FUP</code>)-Nachrichten sowie die asynchrone Bestätigungsverarbeitung (<code>TxConfirmation</code>) für eine gegebene Time Domain.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Zähler (pro <code>TimeDomain</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>cyclicCounter[TimeDomain]</code>:</strong> Laufzeit-Herunterzähler für die zyklische <code>SYNC</code>-Übertragung; wird mit <code>EthTSynGlobalTimeTxPeriod</code> initialisiert.\n</li><li><strong><code>debounceCounter[TimeDomain]</code>:</strong> Entprellzähler zur Einhaltung von Mindestabständen zwischen aufeinanderfolgenden Übertragungen; wird mit <code>EthTSynGlobalTimeDebounceTime</code> initialisiert.\n</li><li><strong><code>cyclicMsgResumeCounter[TimeDomain]</code>:</strong> Haltezähler nach einer unmittelbaren/ereignisgesteuerten Synchronisation (<code>Immediate Time Sync</code>); wird mit <code>EthTSynCyclicMsgResumeTime</code> initialisiert, um die zyklische Übertragung temporär zu unterdrücken.\n</li><li><strong>Protokollzustand (<code>protocol state</code>):</strong> Diskreter Zustandsmerker pro Time Domain mit den Werten <code>&quot;SYNC&quot;</code> und <code>&quot;FUP&quot;</code>.\n</li><li><strong><code>timeBaseUpdateCounter[timeBaseId]</code>:</strong> Aus dem <code>StbM</code> bezogener Update-Zähler zur Erkennung von Zeitbasisaktualisierungen.\n</li><li><strong><code>timeBaseStatus[timeBaseId]</code>:</strong> Bitmaske des Zeitstatus (Prüfung gegen Statusflag <code>GLOBAL_TIME_BASE</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurationsparameter (ECUC-Parameter)</h5>\n<ul class=\"fig-list\"><li><strong><code>EthTSynImmediateTimeSync</code> (Boolean):</strong> Aktiviert die unmittelbare Aussendung bei Aktualisierung der lokalen Zeitbasis.\n</li><li><strong><code>EthTSynGlobalTimeTxPeriod</code> (Float/Time):</strong> Zykluszeit für periodische <code>SYNC</code>-Frames.\n</li><li><strong><code>EthTSynGlobalTimeDebounceTime</code> (Float/Time):</strong> Mindestabstand zwischen Frames.\n</li><li><strong><code>EthTSynCyclicMsgResumeTime</code> (Float/Time):</strong> Verzögerungszeit bis zur Wiederaufnahme regulärer Zyklen nach einem Immediate Sync.\n</li><li><strong><code>EthTSynGlobalTimeFollowUpTimeout</code> (Float/Time):</strong> Maximales Zeitfenster für den Empfang der Tx-Bestätigung (Egress-Timestamp) des <code>SYNC</code>-Frames.\n</li></ul>\n<h5 class=\"fig-section-h5\">Interaktionsschnittstellen &amp; APIs</h5>\n<ul class=\"fig-list\"><li><strong>Unterlagerter Stack (<code>EthIf</code> / <code>Eth</code>):</strong>\n<ul class=\"fig-list\"><li>Sendeanforderung: <code>EthIf_Transmit()</code> für PTP-Frames.\n</li><li>Bestätigung &amp; Timestamping: Asynchroner Callback <code>EthIf_TxConfirmation()</code> liefert <code>E_OK</code> und den hardwarenah erfassten Egress-Sendezeitpunkt t_1.\n</li></ul>\n</li><li><strong>Oberlagerter Stack (<code>StbM</code>):</strong>\n<ul class=\"fig-list\"><li>Bereitstellung von Zeitbasis, Statusflags (<code>GLOBAL_TIME_BASE</code>) und dem <code>timeBaseUpdateCounter</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Jeder Durchlauf in der Task-Schleife der <code>EthTSyn_MainFunction()</code> folgt einer vierphasigen Kaskade:</p>\n<h5 class=\"fig-section-h5\">Phase 1: Zähler-Dekrementierung</h5>\n<p class=\"fig-p\">Parallel bzw. sequenziell werden aktive Zähler dekrementiert:</p>\n<ol class=\"fig-list\"><li>Falls <code>EthTSynImmediateTimeSync == TRUE</code> und <code>cyclicMsgResumeCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeDebounceTime &gt; 0</code> und <code>debounceCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeTxPeriod &gt; 0</code> und <code>cyclicCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Transmissions- und Quittierungsprüfung (<code>Timesync Message pending?</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Pfad <code>ongoing and not completed yet</code>:</strong> Es steht noch eine Tx-Bestätigung aus (kein Callback erfolgt). Keine Neuübertragung möglich; Verzweigung direkt zum Endknoten.\n</li><li><strong>Pfad <code>SYNC transmission completed</code>:</strong> Tx-Confirmation für <code>SYNC</code> wurde empfangen:\n<ul class=\"fig-list\"><li><em>Prüfung:</em> Erfolgreich (<code>E_OK</code>) innerhalb des Timeout-Fensters <code>EthTSynGlobalTimeFollowUpTimeout</code>?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Setze <code>protocol state = &quot;FUP&quot;</code>. Falls Nachrichtentyp <code>immediate</code>: Setze <code>cyclicMsgResumeCounter = EthTSynCyclicMsgResumeTime</code> und setze <code>cyclicCounter = 0</code>. Anschließend: Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein (Timeout/Fehler):</strong> Abbruch des Sequenzschritts, Verzweigung zum Zyklusende.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>FUP transmission completed</code>:</strong> Tx-Confirmation für <code>FUP</code> wurde empfangen:\n<ul class=\"fig-list\"><li>Setze <code>protocol state = &quot;SYNC&quot;</code>.\n</li><li><em>Prüfung:</em> War <code>FUP</code>-Übertragung erfolgreich?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein:</strong> Kein Reset des Debounce-Counters.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>no transmission ongoing</code>:</strong> Direkter Übergang zur Sendeentscheidung (Phase 3).\n</li></ul>\n<h5 class=\"fig-section-h5\">Phase 3: Sendeentscheidung &amp; Arbitrierung</h5>\n<p class=\"fig-p\">Voraussetzung für jegliche Transmission ist <code>debounceCounter[TimeDomain] == 0</code>. Ist dieser &gt; 0, terminiert der Durchlauf ohne Sendeaktion.</p>\n<ol class=\"fig-list\"><li><strong>Prüfung Protokollzustand:</strong>\n<ul class=\"fig-list\"><li>Ist <code>protocol state != &quot;SYNC&quot;</code> (d. h. <code>&quot;FUP&quot;</code>):\n<ul class=\"fig-list\"><li><strong>Aktion:</strong> <code>Transmit FUP Message</code> (Aussendung der <code>Follow_Up</code>-Nachricht mit dem im vorangegangenen Sync-Tx-Confirmation ermittelten präzisen Egress-Timestamp t_1).\n</li></ul>\n</li></ul>\n</li><li><strong>Wenn <code>protocol state == &quot;SYNC&quot;</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Pfad A – Immediate Sync:</strong> Falls <code>EthTSynImmediateTimeSync == TRUE</code>:\n<ul class=\"fig-list\"><li>Prüfung: Hat sich <code>timeBaseUpdateCounter[timeBaseId]</code> geändert <strong>UND</strong> ist Bit <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> gesetzt?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Immediate Sync Message</code> (sofortige Triggerung).\n</li><li><strong>Nein:</strong> Fallback auf Pfad B via <code>cyclicMsgResumeCounter == 0?</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad B – Cyclic Sync:</strong> Wenn <code>cyclicMsgResumeCounter == 0</code> (oder <code>ImmediateTimeSync == FALSE</code>):\n<ul class=\"fig-list\"><li>Prüfung: <code>(EthTSynGlobalTimeTxPeriod &gt; 0) &amp;&amp; (cyclicCounter == 0) &amp;&amp; (timeBaseStatus &amp; GLOBAL_TIME_BASE)</code>:\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Cyclic Sync Message</code> und Re-Initialisierung: <code>cyclicCounter = EthTSynGlobalTimeTxPeriod</code>.\n</li><li><strong>Nein:</strong> Keine Übertragung in diesem Zyklus.\n</li></ul>\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Two-Step Sync Mechanismus (IEEE 802.1AS):</strong> Das Diagramm bildet zwingend das Two-Step-Verfahren ab. Ein <code>FUP</code>-Frame kann erst übertragen werden, nachdem der Egress-Timestamp des vorhergehenden <code>SYNC</code>-Frames per <code>TxConfirmation</code> erfolgreich vom Hardware-Ethernet-Controller an das BSW gemeldet wurde.\n</li><li><strong>Hard Deadlines &amp; Timeout-Handling:</strong>\n<ul class=\"fig-list\"><li>Bleibt die Tx-Bestätigung über <code>EthTSynGlobalTimeFollowUpTimeout</code> hinaus aus, verwirft der Stack die Sequenz (kein <code>FUP</code>). Die Time Slaves erkennen den fehlenden Follow-Up und verwerfen den unvollständigen Sync-Zyklus.\n</li></ul>\n</li><li><strong>Jitter- und Periodizitäts-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die Auflösung aller Zähler hängt strikt von der Periodizität der Task ab, in der <code>EthTSyn_MainFunction()</code> aufgerufen wird (z. B. 1 ms oder 5 ms). Die konfigurierten ECUC-Parameter (<code>TxPeriod</code>, <code>DebounceTime</code>, <code>FollowUpTimeout</code>) müssen ganzzahlige Vielfache dieses Task-Intervalls sein.\n</li></ul>\n</li><li><strong>Einfluss von <code>ImmediateTimeSync</code>:</strong>\n<ul class=\"fig-list\"><li>Durch das Setzen von <code>cyclicCounter = 0</code> und Aufziehen des <code>cyclicMsgResumeCounter</code> bei einem unmittelbaren Sync wird eine Phasensynchronisation des zyklischen Senders erzwungen. Dies verhindert ein direktes Aufeinanderfolgen eines ereignisbasierten und eines regulär-zyklischen Sync-Frames („Burst Protection“).\n</li></ul>\n</li><li><strong>Voraussetzung an den StbM:</strong>\n<ul class=\"fig-list\"><li>Ohne gesetztes Status-Flag <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> unterdrückt die Logik sowohl zyklische als auch Immediate-Sync-Nachrichten, um die Verbreitung nicht synchronisierter bzw. ungültiger Master-Zeiten im Netzwerk zu unterbinden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-815162b756075908", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (<code>act EthTSyn Time Master Timesync Message Transmission</code>), ausgeführt im zyklischen Kontext der <code>EthTSyn_MainFunction()</code>.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der normativen Sende- und Zustandslogik eines <em>Time Masters</em> (bzw. Switch-Ports mit Master-Rolle) im BSW-Modul <code>EthTSyn</code> (AUTOSAR Classic Platform, Time Synchronization over Ethernet nach IEEE 802.1AS / gPTP) gemäß SWS-Anforderung <code>[SWS_EthTSyn_00265]</code>.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Modul <code>EthTSyn</code> vermittelt zwischen dem synchronisierten Zeitbasis-Management (<code>StbM</code> – Synchronized Time-Base Manager) und der Ethernet-Treiber-/Interface-Schicht (<code>EthIf</code> / <code>Eth</code>).\n</li><li>Der Ablauf steuert die zeitliche Entprellung, zyklische/ereignisbasierte Transmission von <code>SYNC</code>- und <code>Follow_Up</code> (<code>FUP</code>)-Nachrichten sowie die asynchrone Bestätigungsverarbeitung (<code>TxConfirmation</code>) für eine gegebene Time Domain.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Datenstrukturen &amp; Zähler (pro <code>TimeDomain</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>cyclicCounter[TimeDomain]</code>:</strong> Laufzeit-Herunterzähler für die zyklische <code>SYNC</code>-Übertragung; wird mit <code>EthTSynGlobalTimeTxPeriod</code> initialisiert.\n</li><li><strong><code>debounceCounter[TimeDomain]</code>:</strong> Entprellzähler zur Einhaltung von Mindestabständen zwischen aufeinanderfolgenden Übertragungen; wird mit <code>EthTSynGlobalTimeDebounceTime</code> initialisiert.\n</li><li><strong><code>cyclicMsgResumeCounter[TimeDomain]</code>:</strong> Haltezähler nach einer unmittelbaren/ereignisgesteuerten Synchronisation (<code>Immediate Time Sync</code>); wird mit <code>EthTSynCyclicMsgResumeTime</code> initialisiert, um die zyklische Übertragung temporär zu unterdrücken.\n</li><li><strong>Protokollzustand (<code>protocol state</code>):</strong> Diskreter Zustandsmerker pro Time Domain mit den Werten <code>&quot;SYNC&quot;</code> und <code>&quot;FUP&quot;</code>.\n</li><li><strong><code>timeBaseUpdateCounter[timeBaseId]</code>:</strong> Aus dem <code>StbM</code> bezogener Update-Zähler zur Erkennung von Zeitbasisaktualisierungen.\n</li><li><strong><code>timeBaseStatus[timeBaseId]</code>:</strong> Bitmaske des Zeitstatus (Prüfung gegen Statusflag <code>GLOBAL_TIME_BASE</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Konfigurationsparameter (ECUC-Parameter)</h5>\n<ul class=\"fig-list\"><li><strong><code>EthTSynImmediateTimeSync</code> (Boolean):</strong> Aktiviert die unmittelbare Aussendung bei Aktualisierung der lokalen Zeitbasis.\n</li><li><strong><code>EthTSynGlobalTimeTxPeriod</code> (Float/Time):</strong> Zykluszeit für periodische <code>SYNC</code>-Frames.\n</li><li><strong><code>EthTSynGlobalTimeDebounceTime</code> (Float/Time):</strong> Mindestabstand zwischen Frames.\n</li><li><strong><code>EthTSynCyclicMsgResumeTime</code> (Float/Time):</strong> Verzögerungszeit bis zur Wiederaufnahme regulärer Zyklen nach einem Immediate Sync.\n</li></ul>\n<h5 class=\"fig-section-h5\">Interaktionsschnittstellen &amp; APIs</h5>\n<ul class=\"fig-list\"><li><strong>Unterlagerter Stack (<code>EthIf</code> / <code>Eth</code>):</strong>\n<ul class=\"fig-list\"><li>Sendeanforderung: <code>EthIf_Transmit()</code> für PTP-Frames.\n</li><li>Bestätigung &amp; Timestamping: Asynchroner Callback <code>EthIf_TxConfirmation()</code> liefert <code>E_OK</code> und den hardwarenah erfassten Egress-Sendezeitpunkt t_1.\n</li></ul>\n</li><li><strong>Oberlagerter Stack (<code>StbM</code>):</strong>\n<ul class=\"fig-list\"><li>Bereitstellung von Zeitbasis, Statusflags (<code>GLOBAL_TIME_BASE</code>) und dem <code>timeBaseUpdateCounter</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Jeder Durchlauf in der Task-Schleife der <code>EthTSyn_MainFunction()</code> folgt einer vierphasigen Kaskade:</p>\n<h5 class=\"fig-section-h5\">Phase 1: Zähler-Dekrementierung</h5>\n<p class=\"fig-p\">Parallel bzw. sequenziell werden aktive Zähler dekrementiert:</p>\n<ol class=\"fig-list\"><li>Falls <code>EthTSynImmediateTimeSync == TRUE</code> und <code>cyclicMsgResumeCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeDebounceTime &gt; 0</code> und <code>debounceCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li><li>Falls <code>EthTSynGlobalTimeTxPeriod &gt; 0</code> und <code>cyclicCounter[TimeDomain] &gt; 0</code>: Dekrement.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Transmissions- und Quittierungsprüfung (<code>Timesync Message ongoing?</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Pfad <code>ongoing and not completed yet</code>:</strong> Es steht noch eine Tx-Bestätigung aus (kein Callback erfolgt). Keine Neuübertragung möglich; Verzweigung direkt zum Endknoten.\n</li><li><strong>Pfad <code>SYNC transmission completed</code>:</strong> Tx-Confirmation für <code>SYNC</code> wurde empfangen:\n<ul class=\"fig-list\"><li><em>Prüfung:</em> Erfolgreich (<code>E_OK</code>)?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Setze <code>protocol state = &quot;FUP&quot;</code>. Falls Nachrichtentyp <code>immediate</code>: Setze <code>cyclicMsgResumeCounter = EthTSynCyclicMsgResumeTime</code> und setze <code>cyclicCounter = 0</code>. Anschließend: Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein (Fehler):</strong> Abbruch des Sequenzschritts, Verzweigung zum Zyklusende.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>FUP transmission completed</code>:</strong> Tx-Confirmation für <code>FUP</code> wurde empfangen:\n<ul class=\"fig-list\"><li>Setze <code>protocol state = &quot;SYNC&quot;</code>.\n</li><li><em>Prüfung:</em> War <code>FUP</code>-Übertragung erfolgreich?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> Lade <code>debounceCounter = EthTSynGlobalTimeDebounceTime</code>.\n</li><li><strong>Nein:</strong> Kein Reset des Debounce-Counters.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad <code>no transmission ongoing</code>:</strong> Direkter Übergang zur Sendeentscheidung (Phase 3).\n</li></ul>\n<h5 class=\"fig-section-h5\">Phase 3: Sendeentscheidung &amp; Arbitrierung</h5>\n<p class=\"fig-p\">Voraussetzung für jegliche Transmission ist <code>debounceCounter[TimeDomain] == 0</code>. Ist dieser &gt; 0, terminiert der Durchlauf ohne Sendeaktion.</p>\n<ol class=\"fig-list\"><li><strong>Prüfung Protokollzustand:</strong>\n<ul class=\"fig-list\"><li>Ist <code>protocol state != &quot;SYNC&quot;</code> (d. h. <code>&quot;FUP&quot;</code>):\n<ul class=\"fig-list\"><li><strong>Aktion:</strong> <code>Transmit FUP Message</code> (Aussendung der <code>Follow_Up</code>-Nachricht mit dem im vorangegangenen Sync-Tx-Confirmation ermittelten Egress-Timestamp t_1).\n</li></ul>\n</li></ul>\n</li><li><strong>Wenn <code>protocol state == &quot;SYNC&quot;</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Pfad A – Immediate Sync:</strong> Falls <code>EthTSynImmediateTimeSync == TRUE</code>:\n<ul class=\"fig-list\"><li>Prüfung: Hat sich <code>timeBaseUpdateCounter[timeBaseId]</code> geändert <strong>UND</strong> ist Bit <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> gesetzt?\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Immediate Sync Message</code> (sofortige Triggerung).\n</li><li><strong>Nein:</strong> Fallback auf Pfad B via <code>cyclicMsgResumeCounter == 0?</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Pfad B – Cyclic Sync:</strong> Wenn <code>cyclicMsgResumeCounter == 0</code> (oder <code>ImmediateTimeSync == FALSE</code>):\n<ul class=\"fig-list\"><li>Prüfung: <code>(EthTSynGlobalTimeTxPeriod &gt; 0) &amp;&amp; (cyclicCounter == 0) &amp;&amp; (timeBaseStatus &amp; GLOBAL_TIME_BASE)</code>:\n<ul class=\"fig-list\"><li><strong>Ja:</strong> <code>Transmit Cyclic Sync Message</code> und Re-Initialisierung: <code>cyclicCounter = EthTSynGlobalTimeTxPeriod</code>.\n</li><li><strong>Nein:</strong> Keine Übertragung in diesem Zyklus.\n</li></ul>\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Two-Step Sync Mechanismus (IEEE 802.1AS):</strong> Das Diagramm bildet das Two-Step-Verfahren ab. Ein <code>FUP</code>-Frame kann erst übertragen werden, nachdem der Egress-Timestamp des vorhergehenden <code>SYNC</code>-Frames per <code>TxConfirmation</code> erfolgreich (<code>E_OK</code>) an das BSW gemeldet wurde.\n</li><li><strong>Quittierungsprüfung:</strong> Schlägt die Tx-Bestätigung der <code>SYNC</code>-Nachricht fehl (<code>E_OK</code> bleibt aus), wird der Protokollzustand nicht auf <code>&quot;FUP&quot;</code> gesetzt und keine Folgeübertragung eingeleitet.\n</li><li><strong>Jitter- und Periodizitäts-Konfiguration:</strong> Die Auflösung aller Zähler hängt strikt von der Periodizität der Task ab, in der <code>EthTSyn_MainFunction()</code> aufgerufen wird (z. B. 1 ms oder 5 ms). Die konfigurierten ECUC-Parameter (<code>TxPeriod</code>, <code>DebounceTime</code>) müssen ganzzahlige Vielfache dieses Task-Intervalls sein.\n</li><li><strong>Einfluss von <code>ImmediateTimeSync</code>:</strong> Durch das Setzen von <code>cyclicCounter = 0</code> und Aufziehen des <code>cyclicMsgResumeCounter</code> bei einem unmittelbaren Sync wird eine Phasensynchronisation des zyklischen Senders erzwungen. Dies verhindert ein direktes Aufeinanderfolgen eines ereignisbasierten und eines regulär-zyklischen Sync-Frames („Burst Protection“).\n</li><li><strong>Voraussetzung an den StbM:</strong> Ohne gesetztes Status-Flag <code>GLOBAL_TIME_BASE</code> im <code>timeBaseStatus</code> unterdrückt die Logik sowohl zyklische als auch Immediate-Sync-Nachrichten, um die Verbreitung nicht synchronisierter bzw. ungültiger Master-Zeiten im Netzwerk zu unterbinden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-78f6194e34bbcbee", "to": "FIG-2028f8ea3f62ff30", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Entscheidungsknoten:</strong> Beschriftung von <code>Timesync Message for Time Domain pending?</code> zu <code>Timesync Message for Time Domain ongoing?</code> geändert (Angleichung an die ausgehenden Kantenbeschriftungen).\n</li><li><strong>UML-Rahmen:</strong> Äußerer Diagrammrahmen samt Titelkopf (<code>act EthTSyn Time Master Timesync Message Transmission</code>) entfernt.\n</li><li><strong>Farbgebung:</strong> Hintergrundfüllung der Aktionsknoten von Orange auf Weiß umgestellt.\n</li></ul>"}, {"from": "FIG-2028f8ea3f62ff30", "to": "FIG-815162b756075908", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>SYNC-Quittierungsprüfung:</strong> Im Entscheidungsknoten zur Bestätigung der <code>SYNC</code>-Übertragung wurde die Timeout-Prüfung <code>within EthTSynGlobalTimeFollowUpTimeout interval</code> entfernt; die Verzweigungsbedingung lautet nun verkürzt <code>SYNC Message Transmission for Time Domain successful (i.e., tx confirmation returned E_OK)?</code>.\n</li><li><strong>Konfigurationsparameter:</strong> Der ECUC-Parameter <code>EthTSynGlobalTimeFollowUpTimeout</code> ist nicht mehr Teil des Schaubilds.\n</li></ul>"}]};
